/**
 * Migration runner.
 *
 * The SQL under `drizzle/` is generated by `drizzle-kit generate` from
 * `db/schema.ts`, and this applies it through Drizzle's migrator, which records
 * each applied migration in `__drizzle_migrations`. That makes `migrate` safe to
 * call on every boot and keeps the schema and the queries in lockstep.
 *
 * The folder is resolved from this module rather than `process.cwd()`, so the
 * same call works from `apps/api`, from `apps/ws`, and from the tests.
 */
import path from "node:path";
import { fileURLToPath } from "node:url";
import { migrate as runMigrations } from "drizzle-orm/node-postgres/migrator";
import { db } from "./client";

const here = path.dirname(fileURLToPath(import.meta.url));

export const MIGRATIONS_FOLDER = path.resolve(here, "../../drizzle");

export async function migrate(folder: string = MIGRATIONS_FOLDER): Promise<void> {
  await runMigrations(db, { migrationsFolder: folder });
}
